bool encodeMOBOPackStatusMessage(const MOBOPackStatusMessage& msg, CanFrame& frame) {
    const MessageDefinition* def = getMessageDefinition(CanMessageId::CAN_MSG_MOBO_PACKSTATUS);
    if (def == nullptr) {
        return false;
    }

    frame.id = def->canId;
    frame.dlc = def->dlc;
    frame.extended = def->extended;
    std::memset(frame.data, 0, sizeof(frame.data));

    {
        const uint64_t rawValue = msg.gPIOBSPD ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 0U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOCHARGE ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 1U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOAMS ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 2U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOLATCH ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 3U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOHVACT ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 4U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOAIRN ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 5U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOIMD ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 6U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIODRDY ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 7U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIORTML ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 8U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOTSSI ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 9U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOAMSOK ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 10U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOPRECHOK ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 11U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIORED ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 12U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOGREEN ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 13U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = msg.gPIOFANEN ? 1ULL : 0ULL;
        insertIntelBits(frame.data, 14U, 1U, rawValue);
    }
    {
        const uint64_t rawValue = static_cast<uint64_t>(msg.bMSState);
        insertIntelBits(frame.data, 16U, 8U, rawValue);
    }
    {
        const uint64_t rawValue = static_cast<uint64_t>(msg.sOC);
        insertIntelBits(frame.data, 24U, 8U, rawValue);
    }
    {
        const uint64_t rawValue = static_cast<uint64_t>(msg.packVoltage);
        insertIntelBits(frame.data, 32U, 8U, rawValue);
    }

    return true;
}

